FConvex(TArray<FPlaneType>&& InPlanes, TArray<FVec3Type>&& InVertices)
    : FImplicitObject(EImplicitObject::IsConvex | EImplicitObject::HasBoundingBox, ImplicitObjectType::Convex)
	, Planes(MoveTemp(InPlanes))
    , Vertices(MoveTemp(InVertices))
{
	for (int32 ParticleIndex = 0; ParticleIndex < Vertices.Num(); ++ParticleIndex)
	{
		LocalBoundingBox.GrowToInclude(Vertices[ParticleIndex]);
	}

	// For now we approximate COM and volume with the bounding box

	return 0.0f;
}

virtual const FAABB3 BoundingBox() const override
{
	// LWC : conversion from float to double
	return FAABB3(LocalBoundingBox.Min(), LocalBoundingBox.Max());
}

void InitScaledImplicit(const FVec3& Scale, FRealSingle InMargin = 0)
{
	ensureMsgf((IsScaled(MObject->GetType()) == false), TEXT("Scaled objects should not contain each other."));
	ensureMsgf((IsInstanced(MObject->GetType()) == false), TEXT("Scaled objects should not contain instances."));
	switch (MObject->GetType())
	{
	case ImplicitObjectType::Transformed:
	case ImplicitObjectType::Union:
		check(false);	//scale is only supported for concrete types like sphere, capsule, convex, levelset, etc... Nothing that contains other objects
	default:
		break;
	}
	this->bIsConvex = MObject->IsConvex();
	this->bDoCollide = MObject->GetDoCollide();
	this->OuterMargin = InMargin;
	SetScale(Scale);
}

void UpdateBounds()
{
	const FAABB3 UnscaledBounds = MObject->BoundingBox();
	const FVec3 Vector1 = UnscaledBounds.Min() * MScale;
	MLocalBoundingBox = FAABB3(Vector1, Vector1);	//need to grow it out one vector at a time in case scale is negative
	const FVec3 Vector2 = UnscaledBounds.Max() * MScale;
	MLocalBoundingBox.GrowToInclude(Vector2);
}

// CollisionTolerance:
// For polygonal shapes the collision tolerance is proportional to the size of the smaller object. 
// For quadratic shapes we want a collision tolerance much smaller than the radius.
//
const bool bIsQuadratic0 = ((ImplicitType0 == ImplicitObjectType::Sphere) || (ImplicitType0 == ImplicitObjectType::Capsule));
const bool bIsQuadratic1 = ((ImplicitType1 == ImplicitObjectType::Sphere) || (ImplicitType1 == ImplicitObjectType::Capsule));

// @todo(chaos): should probably be tunable. Used to use the same settings as the margin scale (for convex), but we want to support zero
// margins, but still have a non-zero CollisionTolerance (it is used for matching contact points for friction and manifold reuse)
const FRealSingle ToleranceScale = 0.1f;
const FRealSingle QuadraticToleranceScale = 0.05f;

if (!bIsQuadratic0 && !bIsQuadratic1)
{
	// Only dynamic polytopes objects use margins
	const bool bIsDynamic0 = (GetParticle0() != nullptr) && (FConstGenericParticleHandle(GetParticle0())->IsDynamic());
	const bool bIsDynamic1 = (GetParticle1() != nullptr) && (FConstGenericParticleHandle(GetParticle1())->IsDynamic());
	const FRealSingle DynamicMargin0 = bIsDynamic0 ? FRealSingle(Margin0) : FRealSingle(0);
	const FRealSingle DynamicMargin1 = bIsDynamic1 ? FRealSingle(Margin1) : FRealSingle(0);

	const FRealSingle MaxSize0 = ((Implicit[0] != nullptr) && Implicit[0]->HasBoundingBox()) ? FRealSingle(Implicit[0]->BoundingBox().Extents().GetAbsMax()) : FRealSingle(0);
	const FRealSingle MaxSize1 = ((Implicit[1] != nullptr) && Implicit[1]->HasBoundingBox()) ? FRealSingle(Implicit[1]->BoundingBox().Extents().GetAbsMax()) : FRealSingle(0);
	const FRealSingle MaxSize = FMath::Min(MaxSize0, MaxSize1);
	CollisionTolerance = ToleranceScale * MaxSize;

	// If one shape has a zero margin, enforce a minimum margin to avoid the EPA degenerate case. E.g., Box-Triangle
	// If both shapes have a margin, use the smaller margin on both shapes. E.g., Box-Box

	FGeometryParticleHandle* Particle1,
	const FPerShapeData* InShape1,
	const FReal CullDistance,
	const EContactShapesType ShapePairType,
	const bool bUseManifold,
	const FCollisionContext& Context)
{
	const FImplicitObject* Implicit0 = InShape0->GetLeafGeometry();
	const FBVHParticles* BVHParticles0 = FConstGenericParticleHandle(Particle0)->CollisionParticles().Get();
	const FRigidTransform3& ShapeRelativeTransform0 = (FRigidTransform3)InShape0->GetLeafRelativeTransform();
	const FImplicitObject* Implicit1 = InShape1->GetLeafGeometry();
	const FBVHParticles* BVHParticles1 = FConstGenericParticleHandle(Particle1)->CollisionParticles().Get();
	const FRigidTransform3& ShapeRelativeTransform1 = (FRigidTransform3)InShape1->GetLeafRelativeTransform();

	return Context.GetAllocator()->CreateConstraint(Particle0, Implicit0, InShape0, BVHParticles0, ShapeRelativeTransform0, Particle1, Implicit1, InShape1, BVHParticles1, ShapeRelativeTransform1, CullDistance, bUseManifold, ShapePairType);
